import{t as e}from"./client-bLrIbxMr.js";var t={getMe:async()=>(await e.get(`/drivers/me`)).data,getDrivers:async t=>(await e.get(`/drivers`,{params:t})).data,getDriverById:async t=>(await e.get(`/drivers/${t}`)).data,createDriver:async t=>(await e.post(`/drivers`,t)).data,updateDriver:async(t,n)=>(await e.patch(`/drivers/${t}`,n)).data,extractCdl:async(t,n)=>{let r=new FormData;return r.append(`file`,n),(await e.post(`/drivers/${t}/extract-cdl`,r)).data},getAvailabilityTimeline:async(t,n)=>(await e.get(`/drivers/availability/timeline`,{params:{start_date:t,end_date:n}})).data,getAvailability:async t=>(await e.get(`/drivers/${t}/availability`)).data,createAvailability:async(t,n)=>(await e.post(`/drivers/${t}/availability`,n)).data,updateAvailability:async(t,n,r)=>(await e.patch(`/drivers/${t}/availability/${n}`,r)).data,deleteAvailability:async(t,n)=>(await e.delete(`/drivers/${t}/availability/${n}`)).data,deleteDriver:async t=>(await e.delete(`/drivers/${t}`)).data};export{t};